    "inline_image": "https://images.unsplash.com/photo-1476480862126-209bfaa8edc8?auto=format&fit=crop&w=800&q=80",
    "inline_caption": "Maximal oxygen uptake (VO2 Max) assessment representing cardiorespiratory fitness reserve."
